import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.CXsxtpvq.js";const s="/asset-studio/shots/01-prompts-empty.webp",d="/asset-studio/shots/02-sample-imported.webp",u=JSON.parse('{"title":"시작하기","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/getting-started.md","filePath":"ko/guide/getting-started.md"}'),i={name:"ko/guide/getting-started.md"};function n(l,t,p,h,c,g){return e(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="시작하기" tabindex="-1">시작하기 <a class="header-anchor" href="#시작하기" aria-label="Permalink to &quot;시작하기&quot;">​</a></h1><p>Asset Studio는 내 PC의 <a href="https://github.com/comfyanonymous/ComfyUI" target="_blank" rel="noreferrer">ComfyUI</a>에 붙어서 동작하는 웹 앱입니다. 캐릭터의 외형·의상·표정을 조각으로 나눠 두고, 필요한 조합을 한 번에 생성해 검수한 뒤, 통과한 이미지로 그 캐릭터의 LoRA를 학습합니다.</p><p>이 가이드는 설치를 마친 다음부터 화면을 따라가며 설명합니다. 설치 방법과 필요한 모델·노드 목록은 <a href="https://github.com/kiritype/asset-studio#readme" target="_blank" rel="noreferrer">README</a>를 보세요.</p><h2 id="전체-흐름" tabindex="-1">전체 흐름 <a class="header-anchor" href="#전체-흐름" aria-label="Permalink to &quot;전체 흐름&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>프롬프트 라이브러리 → 이미지 생성 → 갤러리에서 검수 → LoRA 학습 → LoRA를 켜고 다시 생성</span></span>
<span class="line"><span>                                        ↘ 이미지 도구(태그·인페인트·배경 투명화·가림 처리)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>메뉴</th><th>하는 일</th></tr></thead><tbody><tr><td>프롬프트 수정</td><td>작품·캐릭터·의상·감정 같은 프롬프트 조각을 만들고 고칩니다.</td></tr><tr><td>작업</td><td>캐릭터 × 의상 × 감정 × 장수를 골라 대기열에 넣습니다.</td></tr><tr><td>실험실</td><td>프롬프트 하나를 여러 시드나 설정값으로 생성해 비교합니다.</td></tr><tr><td>이미지 도구</td><td>메타데이터 읽기, 태그 분석, 인페인트, 배경 투명화, 가림 처리, WebP 변환.</td></tr><tr><td>LoRA</td><td>통과한 이미지로 데이터셋을 만들고 학습해 등록합니다.</td></tr><tr><td>갤러리</td><td>생성한 이미지를 보고 통과/실패로 검수합니다.</td></tr><tr><td>설정</td><td>언어·테마, ComfyUI 연결, LoRA 학습, GPU 사용 조건.</td></tr></tbody></table><p>화면 오른쪽 위에는 ComfyUI 연결 상태와 대기열 버튼이 늘 보입니다.</p><h2 id="실행" tabindex="-1">실행 <a class="header-anchor" href="#실행" aria-label="Permalink to &quot;실행&quot;">​</a></h2><p><code>launch.bat</code>을 실행하면 브라우저에서 <a href="http://127.0.0.1:8195" target="_blank" rel="noreferrer">http://127.0.0.1:8195</a> 가 열립니다. 생성과 이미지 도구를 쓰려면 ComfyUI가 켜져 있어야 합니다(기본 주소 <a href="http://127.0.0.1:8188" target="_blank" rel="noreferrer">http://127.0.0.1:8188</a>).</p><p>처음 열면 라이브러리가 비어 있습니다.</p><p><img src="`+s+'" alt="빈 프롬프트 라이브러리"></p><h2 id="샘플-작품으로-시작하기" tabindex="-1">샘플 작품으로 시작하기 <a class="header-anchor" href="#샘플-작품으로-시작하기" aria-label="Permalink to &quot;샘플 작품으로 시작하기&quot;">​</a></h2><p><strong>프롬프트 수정</strong> 화면 오른쪽 위의 <strong>샘플 가져오기</strong>를 누르면 예시 작품 &quot;Starlight Academy&quot;가 만들어집니다. 학생 두 명(Lyra Vance, Kai Rowan), 교복과 마법사 로브, 감정 다섯 가지, 구도 두 가지가 들어 있어 바로 생성해 볼 수 있습니다.</p><p><img src="'+d+'" alt="샘플 가져오기 완료"></p><p>샘플에는 생성 설정(모델·샘플러)이 들어 있지 않습니다. 처음 생성할 때 <a href="./generate">이미지 생성</a>의 <strong>생성 설정</strong>에서 모델을 고르세요.</p><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><ol><li><a href="./library">프롬프트 라이브러리</a>에서 샘플이 어떻게 짜여 있는지 봅니다.</li><li><a href="./generate">이미지 생성</a>에서 Lyra의 감정 다섯 가지를 생성합니다.</li><li><a href="./gallery">갤러리와 검수</a>에서 마음에 드는 이미지를 통과시킵니다.</li><li><a href="./lora">LoRA 학습</a>에서 통과한 이미지로 Lyra의 LoRA를 만듭니다.</li></ol>',17)])])}const f=a(i,[["render",n]]);export{u as __pageData,f as default};
